UPDATE ai_agent_working_memory_turn SET status = 2
WHERE session_id = #{sessionId} AND memory_scope = 'main' AND status IN (0, 1) AND deleted = 0
  AND id IN #{turnId}

UPDATE ai_agent_working_memory_turn
SET message_count = message_count + 1, token_estimate = token_estimate + #{tokenEstimate}
WHERE id = #{turnId} AND status = 0 AND message_count = #{seqNo} AND deleted = 0
